b.concept('governance_hook','Governance hook declaration','Stable hook reference and opaque implementation configuration attached to GraphFunction.declarations, GraphVector.declarations, Job.policy_hooks, Role.policy_hooks, Module.policy_hooks or CandidateFamily.policy_hints, covering at least dispatch, evaluation, escalation, deterministic proof, closure and assurance.',[(0,17,21)])
