b.latitude('hook_declaration_latitude',['governance_hook'],['Declare stable references and opaque config, with declared scope/precedence across callable, vector, Job, Role, Module and candidate-family surfaces.','Assurance hooks may carry authority snapshot, evidence adaptation, ambiguity classification, closure policy and gain adaptation while assurance meaning stays engine-owned.','Traversal modulation config may carry strategy owners/labels, scheduling primitives, obligation schedules, order, phase gates, bounded batches and bounded same-edge continuation.'],['Defining downstream strategy meanings such as steel-thread or waterfall as GTL law.'],[(0,21,23),(0,33,39)])
b.constraint('published_assurance_completeness',['governance_hook'],'Authored GraphFunctions and vectors must declare assurance hook references and boundary intent through GTL without hidden runtime side doors completing the published contract. Traversal modulation is hook/config truth, never hidden config or prompt prose; vectors are primary edge qualifiers, callable/Role defaults follow explicit precedence.',[(0,35,39)])
b.constraint('construction_consciousness_hook',['governance_hook'],'Published abg.fp_consciousness may carry observation adaptation, action-catalog adaptation, observation-action binding, construction priority, affect priority, intent admissibility, value scoring, progress classification, escalation and intent-rendering references/opaque config. ABG remains admission/projection owner; affect adjustments are ABG-derived projection rows, never GTL-emitted authority.',[(0,41,41)])
b.constraint('construction_hook_precedence',['governance_hook'],'For a selected construction action, abg.fp_consciousness precedence is declared/replayable and defaults to vector > GraphFunction > Job > Role > Module > visible installed fallback. Malformed present declarations fail closed; absence uses visible default.',[(0,43,43)],conditions=['Selection of a construction action.'])
b.constraint('assurance_hook_precedence',['governance_hook'],'abg.edge_assurance_contract precedence is declared/replayable and defaults to vector > GraphFunction > Job > Role > Module > visible installed fallback. Malformed present declarations fail closed. Absence resolves to F_H by absentia, not automated closure.',[(0,45,45)])
b.constraint('finding_admission_boundary',['governance_hook'],'Consequential F_P hook returns are findings, not engine authority. GTL may constrain shape/policy refs, but ABG records hook action and admits or rejects findings before deriving any ledger, projection, traversal, intent, event or closure truth.',[(0,47,47)])
b.constraint('effective_target_hook',['governance_hook'],'Every vector output has mandatory effective gtl.target_carrier_contract: vector-local declaration > visible GTL defaults config bundle. Local absence is lawful only if the visible bundle supplies a generic output template. Missing defaults, null binding or malformed declaration fails closed.',[(0,49,49)],exceptions=['Local absence is lawful with a visible generic output template.'])
b.constraint('composition_hook_precedence',['governance_hook'],'Closure-capable, mixed-regime, optimized and construction-substrate boundaries declare replayable abg.fn_composition. Default precedence is vector > GraphFunction > Job > Role > Module > visible config defaults or published template. Malformed present declarations fail closed.',[(0,51,51)],conditions=['The boundary is closure-capable, mixed-regime, optimized or construction-substrate.'])
b.constraint('composition_hook_owner_split',['governance_hook'],'Composition config may carry host, ordered regimes, standards/policy/carrier/assurance contexts, deterministic closure and optimization references/config, but no Product strategy semantics. GTL validator checks the selected contract, HoG traverses admitted composition and ABG admits runtime facts under FN-COMPOSITION.',[(0,53,59)])
b.constraint('observer_reuses_existing_hooks',['governance_hook'],'Executive-observer tuning reuses fp_consciousness, fn_composition, evaluate.C, policy hooks and result interfaces unless a later Product/requirement reprice proves a specific expressiveness gap. A Product observer hook supplies only policy/prompt references, never replay truth, events, continuation, closure or a Product-local loop.',[(0,61,66)],exceptions=['A later Product and requirement reprice may prove a specific expressiveness gap.'])
b.constraint('identity_bearing_types',['opaque_identity'],'Every identity-bearing first-class declaration has opaque id distinct from name; at minimum Graph, GraphVector, Node, GraphFunction, RefinementBoundary, CandidateFamily, Role and Job are identity-bearing. Name supplies no targeting semantics. Targeting/replacement/referencing uses id, including substitution of a specific vector. Preserve identity across publication, materialization, candidate and boundary references for replayable targeting.',[(3,17,19),(3,23,29)])
b.latitude('identity_creation',['opaque_identity'],['Automatically mint identity by default.','Authors may supply an explicit id where lawful.'],['Equating structural comparison to object identity.','Using human-readable names as declaration targets.'],[(3,21,27)])
b.constraint('interface_law',['interface_satisfaction'],'Inputs and outputs are designated node roles, not another structural type. Composition requires first outputs to satisfy second inputs. Substitution requires inner refinement to preserve outer contract. Satisfaction preserves node schema and Markov truth; interface-equivalent functions are interchangeable at the boundary, and inline materialization preserves the callable outer interface exactly.',[(6,17,27)])
b.constraint('job_callable_binding',['job','contract_ref'],'Every Job references one or more published GraphFunction contracts through ContractRef(kind,target_id), currently kind=graph_function. No semantic Job targets bare vectors: those are internal structure under its bound callable.',[(9,20,24),(9,34,34)])
b.constraint('job_runtime_distinctions',['job'],'Job persists across time; Run is one engine-owned realization and Worker is concrete engine-owned actor identity. Neither is interchangeable with durable semantic work.',[(9,28,30)])
