b.constraint('language_structure_capabilities',['capability_model'],'Provide declarative typed program law independently of host parser shape; inspectable attributes, schema/hook/context/authority references; Graph/Node/vector/interface/callable boundaries and stable identity; and edge, identity, compose, substitute, recurse, fan-out, fan-in, gate, promote, same-object algebra.',[(13,45,58)])
b.constraint('language_callable_and_publication_capabilities',['capability_model'],'Publish GraphFunctions as reusable callable work with outer interfaces and materializable/referenceable structure, not whole Programs, overlays, workspace shells or controllers. Publish node types for contract/type-reference/composed-type/type-sensitive composition reuse as language conformance, not runtime work. Declare Modules, Jobs, Roles, ContractRefs, public starts, candidate/refinement boundaries and membership; selection/refinement declarations do not themselves select traversal.',[(13,60,74)])
b.constraint('language_assets_compute_requirements',['capability_model'],'Declare typed asset/prompt constructors, renderers, output contracts, authority slots and proof obligations; declare hook/plugin/result boundaries preserving ABG admission/events/ledgers/fold/transition/replay ownership. Declare F_D/F_P/F_H composition without F_P/F_H closure or runtime-selection authority, and requirement terms/relations/bundles/spans/lifecycle compositions/proof roles as authoring surfaces for ABG requirements algebra.',[(13,76,90)])
b.constraint('language_validation_runtime_mapping',['capability_model'],'Non-lowering GTL validation precedes runtime admission and reports typed conformance, traversal-unit shape, capability coverage, publication inventory and proof/readiness issues without executable plans. Language signal must suffice for direct HoG traversal and ABG admission/projection/replay while preserving the ownership split.',[(13,92,100)])
